//! OpenAI-compatible HTTP API (`/v1/chat/completions`, `/v1/models`).//!//! This module provides a direct LLM proxy through the web gateway so any//! standard OpenAI client library can use IronClaw as a backend by simply//! changing the `base_url`.use std::sync::Arc;use axum::{    Json,    extract::State,    http::{HeaderValue, StatusCode},    response::{        IntoResponse, Response,        sse::{Event, KeepAlive, Sse},    },};use serde::{Deserialize, Serialize};use crate::llm::{    ChatMessage, CompletionRequest, FinishReason, Role, ToolCall, ToolCompletionRequest,    ToolDefinition,};use super::server::GatewayState;const MAX_MODEL_NAME_BYTES: usize = 256;// ---------------------------------------------------------------------------// OpenAI request types// ---------------------------------------------------------------------------#[derive(Debug, Deserialize)]pub struct OpenAiChatRequest {    pub model: String,    pub messages: Vec<OpenAiMessage>,    #[serde(default)]    pub temperature: Option<f32>,    #[serde(default)]    pub max_tokens: Option<u32>,    #[serde(default)]    pub stream: Option<bool>,    #[serde(default)]    pub tools: Option<Vec<OpenAiTool>>,    #[serde(default)]    pub tool_choice: Option<serde_json::Value>,    #[serde(default)]    pub stop: Option<serde_json::Value>,}#[derive(Debug, Clone, Serialize, Deserialize)]pub struct OpenAiMessage {    pub role: String,    #[serde(default, skip_serializing_if = "Option::is_none")]    pub content: Option<String>,    #[serde(default, skip_serializing_if = "Option::is_none")]    pub name: Option<String>,    #[serde(default, skip_serializing_if = "Option::is_none")]    pub tool_call_id: Option<String>,    #[serde(default, skip_serializing_if = "Option::is_none")]    pub tool_calls: Option<Vec<OpenAiToolCall>>,}#[derive(Debug, Clone, Serialize, Deserialize)]pub struct OpenAiTool {    #[serde(rename = "type")]    pub tool_type: String,    pub function: OpenAiFunction,}#[derive(Debug, Clone, Serialize, Deserialize)]pub struct OpenAiFunction {    pub name: String,    #[serde(default, skip_serializing_if = "Option::is_none")]    pub description: Option<String>,    #[serde(default, skip_serializing_if = "Option::is_none")]    pub parameters: Option<serde_json::Value>,}#[derive(Debug, Clone, Serialize, Deserialize)]pub struct OpenAiToolCall {    pub id: String,    #[serde(rename = "type")]    pub call_type: String,    pub function: OpenAiToolCallFunction,}#[derive(Debug, Clone, Serialize, Deserialize)]pub struct OpenAiToolCallFunction {    pub name: String,    pub arguments: String,}// ---------------------------------------------------------------------------// OpenAI response types (non-streaming)// ---------------------------------------------------------------------------#[derive(Debug, Serialize)]pub struct OpenAiChatResponse {    pub id: String,    pub object: &'static str,    pub created: u64,    pub model: String,    pub choices: Vec<OpenAiChoice>,    pub usage: OpenAiUsage,}#[derive(Debug, Serialize)]pub struct OpenAiChoice {    pub index: u32,    pub message: OpenAiMessage,    pub finish_reason: String,}#[derive(Debug, Serialize)]pub struct OpenAiUsage {    pub prompt_tokens: u32,    pub completion_tokens: u32,    pub total_tokens: u32,}// ---------------------------------------------------------------------------// OpenAI response types (streaming)// ---------------------------------------------------------------------------#[derive(Debug, Serialize)]pub struct OpenAiChatChunk {    pub id: String,    pub object: &'static str,    pub created: u64,    pub model: String,    pub choices: Vec<OpenAiChunkChoice>,}#[derive(Debug, Serialize)]pub struct OpenAiChunkChoice {    pub index: u32,    pub delta: OpenAiDelta,    #[serde(skip_serializing_if = "Option::is_none")]    pub finish_reason: Option<String>,}#[derive(Debug, Serialize)]pub struct OpenAiDelta {    #[serde(skip_serializing_if = "Option::is_none")]    pub role: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub content: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub tool_calls: Option<Vec<OpenAiToolCallDelta>>,}#[derive(Debug, Serialize)]pub struct OpenAiToolCallDelta {    pub index: u32,    #[serde(skip_serializing_if = "Option::is_none")]    pub id: Option<String>,    #[serde(rename = "type", skip_serializing_if = "Option::is_none")]    pub call_type: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub function: Option<OpenAiToolCallFunctionDelta>,}#[derive(Debug, Serialize)]pub struct OpenAiToolCallFunctionDelta {    #[serde(skip_serializing_if = "Option::is_none")]    pub name: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub arguments: Option<String>,}// ---------------------------------------------------------------------------// Error response// ---------------------------------------------------------------------------#[derive(Debug, Serialize)]pub struct OpenAiErrorResponse {    pub error: OpenAiErrorDetail,}#[derive(Debug, Serialize)]pub struct OpenAiErrorDetail {    pub message: String,    #[serde(rename = "type")]    pub error_type: String,    pub param: Option<String>,    pub code: Option<String>,}// ---------------------------------------------------------------------------// Conversion functions// ---------------------------------------------------------------------------fn parse_role(s: &str) -> Result<Role, String> {    match s {        "system" => Ok(Role::System),        "user" => Ok(Role::User),        "assistant" => Ok(Role::Assistant),        "tool" => Ok(Role::Tool),        _ => Err(format!("Unknown role: '{}'", s)),    }}pub fn convert_messages(messages: &[OpenAiMessage]) -> Result<Vec<ChatMessage>, String> {    messages        .iter()        .enumerate()        .map(|(i, m)| {            let role = parse_role(&m.role).map_err(|e| format!("messages[{}]: {}", i, e))?;            match role {                Role::Tool => {                    let tool_call_id = m.tool_call_id.as_deref().ok_or_else(|| {                        format!("messages[{}]: tool message requires 'tool_call_id'", i)                    })?;                    let name = m                        .name                        .as_deref()                        .ok_or_else(|| format!("messages[{}]: tool message requires 'name'", i))?;                    Ok(ChatMessage::tool_result(                        tool_call_id,                        name,                        m.content.as_deref().unwrap_or(""),                    ))                }                Role::Assistant => {                    if let Some(ref tcs) = m.tool_calls {                        let calls: Vec<ToolCall> = tcs                            .iter()                            .map(|tc| ToolCall {                                id: tc.id.clone(),                                name: tc.function.name.clone(),                                arguments: serde_json::from_str(&tc.function.arguments)                                    .unwrap_or(serde_json::Value::Object(Default::default())),                            })                            .collect();                        Ok(ChatMessage::assistant_with_tool_calls(                            m.content.clone(),                            calls,                        ))                    } else {                        Ok(ChatMessage::assistant(m.content.as_deref().unwrap_or("")))                    }                }                _ => Ok(ChatMessage {                    role,                    content: m.content.as_deref().unwrap_or("").to_string(),                    content_parts: Vec::new(),                    tool_call_id: None,                    name: m.name.clone(),                    tool_calls: None,                }),            }        })        .collect()}pub fn convert_tools(tools: &[OpenAiTool]) -> Vec<ToolDefinition> {    tools        .iter()        .filter(|t| t.tool_type == "function")        .map(|t| ToolDefinition {            name: t.function.name.clone(),            description: t.function.description.clone().unwrap_or_default(),            parameters: t                .function                .parameters                .clone()                .unwrap_or(serde_json::json!({"type": "object", "properties": {}})),        })        .collect()}fn convert_tool_calls_to_openai(calls: &[ToolCall]) -> Vec<OpenAiToolCall> {    calls        .iter()        .map(|tc| OpenAiToolCall {            id: tc.id.clone(),            call_type: "function".to_string(),            function: OpenAiToolCallFunction {                name: tc.name.clone(),                arguments: serde_json::to_string(&tc.arguments).unwrap_or_default(),            },        })        .collect()}pub fn finish_reason_str(reason: FinishReason) -> String {    match reason {        FinishReason::Stop => "stop".to_string(),        FinishReason::Length => "length".to_string(),        FinishReason::ToolUse => "tool_calls".to_string(),        FinishReason::ContentFilter => "content_filter".to_string(),        FinishReason::Unknown => "stop".to_string(),    }}fn normalize_tool_choice(val: &serde_json::Value) -> Option<String> {    match val {        serde_json::Value::String(s) => Some(s.clone()),        serde_json::Value::Object(obj) => {            // { "type": "function", "function": { "name": "foo" } } → "required"            if obj.contains_key("function") {                Some("required".to_string())            } else {                obj.get("type")                    .and_then(|v| v.as_str())                    .map(|s| s.to_string())            }        }        _ => None,    }}fn map_llm_error(err: crate::error::LlmError) -> (StatusCode, Json<OpenAiErrorResponse>) {    let (status, error_type, code) = match &err {        crate::error::LlmError::AuthFailed { .. }        | crate::error::LlmError::SessionExpired { .. } => (            StatusCode::UNAUTHORIZED,            "authentication_error",            "auth_error",        ),        crate::error::LlmError::RateLimited { .. } => (            StatusCode::TOO_MANY_REQUESTS,            "rate_limit_error",            "rate_limit",        ),        crate::error::LlmError::ContextLengthExceeded { .. } => (            StatusCode::BAD_REQUEST,            "invalid_request_error",            "context_length_exceeded",        ),        crate::error::LlmError::ModelNotAvailable { .. } => (            StatusCode::NOT_FOUND,            "invalid_request_error",            "model_not_found",        ),        _ => (            StatusCode::INTERNAL_SERVER_ERROR,            "server_error",            "internal_error",        ),    };    (        status,        Json(OpenAiErrorResponse {            error: OpenAiErrorDetail {                message: err.to_string(),                error_type: error_type.to_string(),                param: None,                code: Some(code.to_string()),            },        }),    )}